    capacity = context['capacity']
    events = context['events']
    order = []
    present = set()
    hits = 0
    misses = 0
    for event in events:
        if event['op'] == 'reset':
            order = []
            present = set()
            hits = 0
            misses = 0
        else:
            key = event['key']
            if key in present:
                hits = hits + 1
                order.remove(key)
                order.append(key)
