def investigate(context, acquire):
    table = {}
    high = 0
    saved = None
    for action in context['actions']:
        op = action['op']
        if op == 'put':
            ident = action['id']
            table[ident] = True
            if ident > high:
                high = ident
        elif op == 'delete':
            table.pop(action['id'], None)
        elif op == 'begin':
            saved = (dict(table), high)
        elif op == 'commit':
            saved = None
        elif op == 'rollback':
            table, high = saved
            saved = None
    return high + 1

